def _backfill() -> None:
    if context.is_offline_mode():
        return
    conn = op.get_bind()
    now = datetime.now(timezone.utc).replace(tzinfo=None)
    # 1) mavjud korxonalarga maxsus raqam (3 harf + 2 raqam)
    customers = sa.table("customers", sa.column("id", sa.Integer), sa.column("code", sa.String))
    taken = {c for (c,) in conn.execute(sa.select(customers.c.code).where(customers.c.code.is_not(None)))}
    for (cid,) in conn.execute(sa.select(customers.c.id).where(customers.c.code.is_(None))).fetchall():
        while True:
            code = "".join(secrets.choice(LETTERS) for _ in range(3)) + f"{secrets.randbelow(100):02d}"
            if code not in taken:
                break
        taken.add(code)
        conn.execute(customers.update().where(customers.c.id == cid).values(code=code))
    # 2) ruxsatlar
    users = sa.table("users", sa.column("id", sa.Integer), sa.column("role", sa.String))
    perms = sa.table("user_permissions", sa.column("user_id", sa.Integer), sa.column("code", sa.String),
                     sa.column("created_at", sa.DateTime))
    have = {(u, c) for u, c in conn.execute(sa.select(perms.c.user_id, perms.c.code))}
    rows = [{"user_id": uid, "code": c, "created_at": now}
            for uid, role in conn.execute(sa.select(users.c.id, users.c.role))
            for c in NEW_PERMS.get(role, []) if (uid, c) not in have]
    if rows:
        op.bulk_insert(perms, rows)
