    forms = sa.table("order_forms", sa.column("id", sa.Integer), sa.column("number", sa.String), sa.column("request_id", sa.Integer),
                     sa.column("print_count", sa.Integer), sa.column("attempts", sa.Integer), sa.column("reprint_allowed", sa.Boolean),
                     sa.column("locked", sa.Boolean), sa.column("created_at", sa.DateTime))
    for rid, vid in conn.execute(sa.select(requests.c.id, shifts.c.vehicle_id).select_from(
            requests.join(shifts, requests.c.shift_id == shifts.c.id)).where(requests.c.vehicle_id.is_(None))).fetchall():
        conn.execute(requests.update().where(requests.c.id == rid).values(vehicle_id=vid))
    open_ids = [r for (r,) in conn.execute(sa.select(requests.c.id).where(
        requests.c.status.in_(["assigned", "enroute", "onsite", "failed"]))).fetchall()]
    for rid in open_ids:
        conn.execute(forms.insert().values(request_id=rid, print_count=0, attempts=0, reprint_allowed=False, locked=False,
                                           created_at=now))
    for (fid,) in conn.execute(sa.select(forms.c.id).where(forms.c.number.is_(None))).fetchall():
        conn.execute(forms.update().where(forms.c.id == fid).values(number=f"{fid:07d}"))


